using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using LoopFive;
class Tests {
 static int passed;static void Assert(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS "+name);passed++;}
 static Engine Free(){Engine e=new Engine();e.Config.Quantize=false;e.Config.Gate=0;e.Config.Master=1;e.Config.Limiter=false;for(int i=0;i<5;i++){e.Tracks[i].Config.LoopSync=false;e.Tracks[i].Config.Level=1;}return e;}
 static AudioClip Tone(int n){float[] l=new float[n],r=new float[n];for(int i=0;i<n;i++){l[i]=(float)Math.Sin(i*2*Math.PI*220/44100)*.1f;r[i]=(float)Math.Sin(i*2*Math.PI*330/44100)*.1f;}return new AudioClip(l,r,120,n/44100.0*2);}
 static void Render(Engine e,int count,float input){float[] data=new float[1024],output=new float[1024];for(int i=0;i<data.Length;i++)data[i]=input;while(count>0){int n=Math.Min(count,512);e.Process(data,output,n);count-=n;}}
 static void Near(float a,float b,string n){Assert(Math.Abs(a-b)<.0001,n+" ("+a+" / "+b+")");}
 static void Main(){Directory.CreateDirectory("work/v2/testdata");try{
  Engine e=Free();e.Action(0);Render(e,1000,.2f);e.Action(0);Assert(e.Tracks[0].Clip.Length==1000&&e.Tracks[0].State==PlayState.Playing,"record/play transition and exact frame count");Near(e.Tracks[0].Clip.L[100],.2f,"captured samples");e.Action(0);Render(e,1,.1f);Near(e.Tracks[0].Clip.L[0],.3f,"overdub writes at rendered position");Near(e.Tracks[0].Clip.L[1],.2f,"overdub leaves following frame untouched");e.Undo(0,false);Near(e.Tracks[0].Clip.L[0],.2f,"undo restores take");Assert(e.Tracks[0].Playing&&Math.Abs(e.Tracks[0].Position-1)<.0001,"undo preserves live playback phase");e.Undo(0,true);Near(e.Tracks[0].Clip.L[0],.3f,"redo restores overdub");e.Mark(0,false);e.Clear(0);e.Mark(0,true);Assert(e.Tracks[0].Clip.Length==1000,"mark back after clear");
  e.Tracks[0].Config.OneShot=true;e.Action(0);Render(e,1001,0);Assert(e.Tracks[0].State==PlayState.Stopped,"one-shot automatically stops");e.Tracks[0].Config.OneShot=false;e.Tracks[0].Config.Reverse=true;e.Action(0);float[] o=new float[2];e.Process(null,o,1);Near(o[0],.2f,"reverse reads last sample");e.Action(0);Assert(e.Tracks[0].State==PlayState.Playing,"reverse prevents overdub");
  e=Free();e.Config.Bpm=300;e.Config.Quantize=true;e.Tracks[0].Config.LoopSync=true;e.Tracks[0].Config.Measures=1;e.Action(0);Assert(e.Tracks[0].State==PlayState.WaitingRecord,"queued quantized recording");Render(e,35280,0);Assert(e.Tracks[0].State==PlayState.WaitingRecord,"waits until exact bar");Render(e,1,.2f);Assert(e.Tracks[0].State==PlayState.Recording,"starts on bar boundary");Render(e,35280,.2f);Assert(e.Tracks[0].Clip!=null&&Math.Abs(e.Tracks[0].Clip.Length-35280)<=1,"fixed measure automatically closes exact loop");
  e=Free();e.Config.AutoRecord=true;e.Action(0);Render(e,200,0);Assert(e.Tracks[0].State==PlayState.Armed,"auto record waits below threshold");Render(e,10,.2f);Assert(e.Tracks[0].State==PlayState.Recording&&e.Tracks[0].RecordL.Count==10,"auto record starts at threshold sample");
  e=Free();e.Import(0,Tone(100));e.Import(1,Tone(100));e.Config.SinglePlay=true;e.Action(0);e.Action(1);Assert(!e.Tracks[0].Playing&&e.Tracks[1].Playing,"single play stops previous track");e.Tracks[1].Config.StopMode=2;e.Stop(1,false);Assert(e.Tracks[1].StopAtEnd,"stop at loop end scheduled");Render(e,101,0);Assert(!e.Tracks[1].Playing,"stop at loop end executes");
  e=Free();e.Import(0,new AudioClip(new float[]{.1f,.2f,.3f,.4f},new float[]{.1f,.2f,.3f,.4f},120,.01));e.Tracks[0].Config.Pan=1;e.Action(0);e.Process(null,o,1);Near(o[0],0,"pan right removes left");Near(o[1],.1f,"pan right keeps right");e.Tracks[0].Config.Mute=true;e.Process(null,o,1);Near(o[1],0,"mute");
  e=Free();e.Import(0,Tone(1000));e.Action(0);e.Tracks[1].Config.InputL=e.Tracks[1].Config.InputR=false;e.Tracks[1].Config.BounceMask=1;e.Action(1);Render(e,500,0);e.Action(1);Near(e.Tracks[1].Clip.L[100],e.Tracks[0].Clip.L[100],"bounce records other track");
  e.Config.Name="Prueba ñ";e.Config.TrackFx.Bank=2;e.Config.TrackFx.Slots[9]=new FxConfig{Type="DELAY",On=true,Amount=.7f,Sequence=true};e.Config.Rhythm.Kit=15;e.Config.Rhythm.UserSteps[3]=255;e.Tracks[0].Config.FadeIn=true;e.Tracks[0].Config.Speed=.5f;
  Snapshot s=Storage.Capture(e);Storage.Save("work/v2/testdata/session.loop5",s);Snapshot loaded=Storage.Load("work/v2/testdata/session.loop5");Assert(loaded.Config.Name==s.Config.Name&&loaded.Config.TrackFx.Slots[9].Sequence&&loaded.Config.Rhythm.UserSteps[3]==255&&loaded.Config.Tracks[0].Speed==.5f,"session metadata roundtrip");Near(loaded.Clips[0].L[10],s.Clips[0].L[10],"session samples roundtrip");Storage.Save("work/v2/testdata/session.loop5",loaded);Assert(File.Exists("work/v2/testdata/session.loop5.bak"),"atomic replacement keeps backup");
  Wav.Write("work/v2/testdata/float.wav",s.Clips[0],true);AudioClip wav=Wav.Read("work/v2/testdata/float.wav",120);Near(wav.L[100],s.Clips[0].L[100],"float WAV roundtrip");Wav.Write("work/v2/testdata/pcm.wav",s.Clips[0],false);wav=Wav.Read("work/v2/testdata/pcm.wav",120);Assert(Math.Abs(wav.L[100]-s.Clips[0].L[100])<.0001,"PCM WAV roundtrip");
  File.WriteAllBytes("work/v2/testdata/bad.loop5",new byte[]{7,76,79,79,80,53,118,50,255,255,255,127});bool rejected=false;try{Storage.Load("work/v2/testdata/bad.loop5");}catch{rejected=true;}Assert(rejected,"corrupt session rejected");
  e=Free();Midi m=new Midi(e);m.Receive(0x7f14b0);Assert(e.Tracks[0].State==PlayState.Recording,"MIDI CC triggers recording");m.Receive(0x7f14b0);Assert(e.Tracks[0].State==PlayState.Recording,"MIDI CC edge does not retrigger");m.LearnIndex=6;m.Receive(0x4022b1);Assert(e.System.Assignments[6].Channel==2&&e.System.Assignments[6].Controller==34&&m.LearnIndex==-1,"MIDI learn captures channel/CC");m.Receive(0x644090);Assert(e.NoteCount==1&&e.MidiNote==64,"MIDI note on drives synth");m.Receive(0x004080);Assert(e.NoteCount==0,"MIDI note off releases synth");m.Dispose();
  Assert(FxCatalog.Input.Length==49&&FxCatalog.All.Length==53,"effect family catalog counts");Stopwatch dsp=Stopwatch.StartNew();foreach(string type in FxCatalog.All){FxProcessor fx=new FxProcessor();FxConfig c=new FxConfig{Type=type,On=true,Mix=1,Rate=.1f,Amount=.6f,Note=60,Semitones=7};fx.Prepare(c,120,64,true);double energy=0,difference=0;for(int i=0;i<88200;i++){float l=(float)Math.Sin(i*.031)*.2f,r=(float)Math.Sin(i*.043)*.15f,original=l;fx.Tick(ref l,ref r,i/22050.0);if(float.IsNaN(l)||float.IsInfinity(l)||Math.Abs(l)>16.001)throw new Exception("Invalid DSP output "+type);energy+=l*l+r*r;difference+=Math.Abs(l-original);}if(energy<.00001)throw new Exception("Silent effect "+type);if(difference<.01)throw new Exception("Passthrough effect "+type);}Assert(true,"all 53 DSP paths generate finite, non-silent, non-passthrough audio ("+dsp.ElapsedMilliseconds+" ms)");
  e=Free();e.Import(0,Tone(22050));e.Action(0);e.Config.TrackFx.Slots[0]=new FxConfig{Type="DELAY",On=true,Mix=.4f};e.Config.Rhythm.Enabled=true;Wav.RenderMix("work/v2/testdata/mix.wav",Storage.Capture(e),1);wav=Wav.Read("work/v2/testdata/mix.wav",120);Assert(wav.Length==88200,"offline mix exact bar duration");
  using(MasterRecorder recorder=new MasterRecorder()){recorder.Start("work/v2/testdata/master.wav");recorder.Enqueue(new float[1024]);recorder.Enqueue(new float[512]);recorder.Stop();Assert(recorder.Error==null&&Wav.Read("work/v2/testdata/master.wav",120).Length==768,"master recording finalizes WAV header");}
  e=Free();using(NativeAudio audio=new NativeAudio(e)){audio.Start();System.Threading.Thread.Sleep(350);Assert(audio.Ready&&audio.ProcessedFrames>0,"real native audio input/output renders");audio.Stop();audio.Start();System.Threading.Thread.Sleep(150);Assert(audio.Ready&&audio.ProcessedFrames>0,"audio device restart");}
  e=Free();e.Config.Rhythm.Enabled=true;for(int i=0;i<5;i++){e.Import(i,Tone(44100));e.Action(i);}for(int i=0;i<4;i++){e.Config.InputFx.Slots[i]=new FxConfig{On=true,Type=new string[]{"LPF","DIST","DELAY","REVERB"}[i]};e.Config.TrackFx.Slots[i]=new FxConfig{On=true,Type=new string[]{"CHORUS","PHASER","DELAY","REVERB"}[i]};}Stopwatch perf=Stopwatch.StartNew();Render(e,441000,.1f);Assert(perf.ElapsedMilliseconds<10000,"five tracks + eight FX + rhythm faster than real time (10 s in "+perf.ElapsedMilliseconds+" ms)");
  Console.WriteLine("TOTAL "+passed+" checks passed");
 }catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
}
